targets.expr:
sum(
  rate(
    istio_requests_total{response_code!~"[4-5].*", source_app=~"$source_app", destination_service_name=~"$destination_service_name", destination_workload_namespace=~"$destination_workload_namespace", cluster="$cluster"}[${__range_s}s]
      )
   )   
/ 
(
  sum(
    rate(
      istio_requests_total{ source_app=~"$source_app", destination_service_name=~"$destination_service_name", destination_workload_namespace=~"$destination_workload_namespace", cluster="$cluster"}[${__range_s}s]
        )
     ) - 
  (
  sum(
    rate(
      istio_requests_total{response_code=~"404|499", source_app=~"$source_app", destination_service_name=~"$destination_service_name",destination_workload_namespace=~"$destination_workload_namespace", cluster="$cluster"}[${__range_s}s]
        )
     ) 
  or vector(0)
  )
)

sum(rate(istio_request_duration_milliseconds_sum{
  reporter="source",
  cluster="$cluster",
  source_app=~"$source_app",
  destination_service_name=~"$destination_service_name"
}[5m])) by (destination_service_name)
/
sum(rate(istio_request_duration_milliseconds_count{
  reporter="source",
  cluster="$cluster",
  source_app=~"$source_app",
  destination_service_name=~"$destination_service_name"
}[5m])) by (destination_service_name)

histogram_quantile(
  0.99,
  sum by (le)(
    rate(
        istio_request_duration_milliseconds_bucket{
          cluster=~"$cluster",
          source_app=~"$source_app",
          destination_workload_namespace=~"$destination_workload_namespace",
          destination_service_name=~"$destination_service_name",
          response_code!~"404|500|304|499"
        }[5m]
    )
  )
)

